.tag-completed, .tag-resolved, .tag-closed { background: var(--green-dim); color: var(--green); }
.tag-rolled-back { background: var(--red-dim); color: var(--red); }

/* ----- Bars (sparkline-style) ----- */
.bar-row { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
.bar-label { width: 90px; font-size: 12px; color: var(--text-dim); text-align: right; flex-shrink: 0; }
.bar-track { flex: 1; background: var(--bg); border-radius: 3px; height: 18px; overflow: hidden; position: relative; }
.bar-fill { height: 100%; border-radius: 3px; transition: width .3s; }
.bar-val { width: 60px; font-size: 12px; color: var(--text-dim); font-variant-numeric: tabular-nums; }
.bar-val-mono { font-family: var(--font-mono); font-size: 11px; }

.metric-row { display: flex; gap: 24px; flex-wrap: wrap; }
