.metric-item .metric-label { font-size: 11px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.05em; }
.metric-item .metric-value { font-size: 18px; font-weight: 700; margin-top: 2px; }

/* ----- Retention grid ----- */
.retention-grid { display: flex; flex-direction: column; gap: 2px; }
.retention-row { display: flex; align-items: center; gap: 4px; }
