const TITLES = {
  summary: \"Summary\",
  revenue: \"Revenue\",
  funnel: \"Acquisition Funnel\",
  retention: \"Retention Cohorts\",
  health: \"Customer Health\",
  support: \"Support Queue\",
  incidents: \"Incidents\",
  experiments: \"Experiments\",
  deployments: \"Deployments\",
};

