// Northstar Ops Console — Validation script.
// Checks entry points, counts first-party source lines, reports findings.

const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");

const REQUIRED_FILES = [
  "index.html",
  "package.json",
  "styles/main.css",
  "data/seed.js",
  "data/store.js",
  "scripts/format.js",
  "scripts/render-summary.js",
  "scripts/render-revenue.js",
  "scripts/render-funnel.js",
  "scripts/render-retention.js",
  "scripts/render-health.js",
  "scripts/render-support.js",
  "scripts/render-incidents.js",
  "scripts/render-experiments.js",
  "scripts/render-deployments.js",
  "src/app.js",
];

const FIRST_PARTY_EXTS = new Set([".html", ".css", ".js", ".json"]);
const SKIP_DIRS = new Set(["node_modules", ".git", "dist", "build", "tests", "docs"]);

let errors = 0;
let totalLines = 0;
let fileCount = 0;
const fileLines = [];

// ---- Check required files exist ----
console.log("=== Entry Point Check ===");
for (const f of REQUIRED_FILES) {
  const full = path.join(ROOT, f);
  if (!fs.existsSync(full)) {
    console.error(`  MISSING: ${f}`);
    errors++;
  } else {
    console.log(`  OK: ${f}`);
  }
}

// ---- Count lines ----
function countLines(filePath) {
  try {
    const content = fs.readFileSync(filePath, "utf-8");
    const lines = content.split("'"\\n\");
    let nonEmpty = 0;
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.length > 0) nonEmpty++;
    }
    return { total: lines.length, nonEmpty };
  } catch {
    return { total: 0, nonEmpty: 0 };
  }
}

function walk(dir, relPath) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const name = entry.name;
    if (name.startsWith(\".\") && name "'!== ".gitignore") continue;
    const full = path.join(dir, name);
    const rel = relPath ? `${relPath}/${name}` : name;

    if (entry.isDirectory()) {
      if (SKIP_DIRS.has(name)) continue;
      walk(full, rel);
    } else {
      const ext = path.extname(name).toLowerCase();
      if (!FIRST_PARTY_EXTS.has(ext)) continue;
      const { total, nonEmpty } = countLines(full);
      totalLines += total;
      fileCount++;
      fileLines.push({ file: rel, total, nonEmpty });
    }
  }
}

walk(ROOT, "");

// ---- Report ----
console.log("'"\\n=== Line Count Report ===\");
console.log("'`  Files:        ${fileCount}`);
console.log(`  Total lines:  ${totalLines}`);
console.log(`  Non-empty:    ${fileLines.reduce((s, f) => s + f.nonEmpty, 0)}`);

console.log("'"\\n=== Per-File Lines ===\");
const maxName = Math.max(...fileLines.map(f => f.file.length));
for (const f of fileLines) {
  const pad = \" \".repeat(Math.max(2, maxName - f.file.length + 2));
  console.log("'`  ${f.file}${pad}${String(f.total).padStart(4)} total  / ${String(f.nonEmpty).padStart(4)} non-empty`);
}

// ---- Dashboard sections check ----
console.log("'"\\n=== Dashboard Sections ===\");
const htmlContent = fs.readFileSync(path.join(ROOT, \"index.html\"), \"utf-8\");
const sections = [
  \"summary\", \"revenue\", \"funnel\", \"retention\",
  \"health\", \"support\", \"incidents\", \"experiments\", \"deployments\",
];
let sectionCount = 0;
for (const s of sections) {
  const found = htmlContent.includes("'`id="section-${s}"`);
  console.log(`  ${found ? "✓" : "✗"} ${s}`);
  if (found) sectionCount++;
}
console.log(`  Sections: ${sectionCount}/9`);

// ---- Summary ----
console.log(`'"\\n=== Result: "'${errors === 0 ? "PASS" : "FAIL"} ===`);
if (errors > 0) {
  console.log(`  ${errors} required file(s) missing.`);
  process.exit(1);
}
console.log("  All entry points present. Ready to preview with: npm run preview");
process.exit(0);
EOF'

