function eq(actual, expected, label) { total++; const a = JSON.stringify(actual), e = JSON.stringify(expected); if (a === e) passed++; else { failed++; console.error(`  FAIL: ${label} — expected ${e}, got ${a}`); } }

const SECTION_NAMES = [
