eq(attachCount, 1, `Exactly 1 attachFixtures call (found ${attachCount})`);

// 7. The IIFE `(function init() {...})()` closes the file
const lastNonEmpty = lines.filter(l => l.trim().length > 0).pop() || "";
assert(lastNonEmpty.includes("})();") || lastNonEmpty.includes("})()"),
  `Last non-empty line closes IIFE: "${lastNonEmpty.slice(0, 40)}"`);

// 8. No code after the IIFE closing
const iifeClose = src.lastIndexOf("})();");
if (iifeClose >= 0) {
