  html += `
    <div class="panel">
      <h3>Roadmap Bets</h3>
      <div class="table-wrap">
        <table><thead><tr><th>Initiative</th><th>ARR Impact</th><th>Prob.</th><th>ETA</th><th>Expected</th></tr></thead><tbody>
        ${roadmapBets.map(b => `
          <tr><td>${b.name}</td><td>${FMT.currency(b.est_arr_impact)}</td>
