  return {
    total: detected.length,
    qualified: byLevel.qualified || 0,
    approaching: byLevel.approaching || 0,
    qualified_mrr: qualifiedMRR,
    top_qualified: detected.filter(d => d.pqa_level === "qualified").slice(0, 10),
  };
}
